# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from data_loader import build_train_val_dataloaders
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score

import timm

# 1. Setup
NUM_SPECIES = 206
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")

# 2. Data Loaders
train_loader, val_loader = build_train_val_dataloaders(
    batch_size=128,
    augment=True,
    val_split=0.2
)

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

# 3. Model Architecture (Transfer Learning)
class BirdCLEFModel(nn.Module):
    def __init__(self, num_classes):
        super().__init__()
        self.base_model = timm.create_model("efficientnet_b0", pretrained=True, in_chans=1, num_classes=0)
        
        # Unfreeze the base model weights
        for param in self.base_model.parameters():
            param.requires_grad = True  # Changed from False to True
                
        self.classifier = nn.Sequential(
            nn.Linear(int(self.base_model.num_features), 256), 
            nn.ReLU(),
            nn.Dropout(0.5),
            nn.Linear(256, num_classes)
        )
        
    def forward(self, x):
        features = self.base_model(x)
        logits = self.classifier(features)
        return logits

model = BirdCLEFModel(num_classes=NUM_SPECIES).to(device)

# 4. Optimizer, Loss, and AMP Scaler
criterion = nn.BCEWithLogitsLoss()

# Pass ALL parameters and lower the learning rate for fine-tuning
optimizer = optim.Adam(model.parameters(), lr=0.0001) 
scaler = torch.amp.GradScaler("cuda") # type: ignore
max_epochs = 3

# --- YOUR TASK: WRITE THE FULL TRAINING AND VALIDATION LOOPS BELOW ---
# Inside your validation metric calculation block, use this safe filtering method:

all_train_losses = []

for epoch in range(max_epochs):
    model.train()
    train_loss = 0.0
    for batch_idx, (inputs, labels) in enumerate(tqdm(train_loader)):
        inputs, labels = inputs.to(device), labels.to(device)
        
        optimizer.zero_grad()
        
        with torch.amp.autocast("cuda"):
            outputs = model(inputs)
            loss = criterion(outputs, labels.float())
        
        scaler.scale(loss).backward()
        
        # Unscale gradients before calling the step of the optimizer
        scaler.unscale_(optimizer)
        
        # Clip gradients to prevent exploding gradients
        torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)
        
        # Step the optimizer and update the scaler
        scaler.step(optimizer)
        scaler.update()
        
        train_loss += loss.item()
    
    all_train_losses.append(train_loss / len(train_loader))
    print(f"Epoch [{epoch+1}/{max_epochs}], Train Loss: {train_loss / len(train_loader):.4f}")

# Validation Loop
model.eval()
all_preds = []
all_labels = []

with torch.no_grad():
    for inputs, labels in tqdm(val_loader):
        inputs, labels = inputs.to(device), labels.to(device)
        
        with torch.amp.autocast("cuda"):
            outputs = model(inputs)
        
        preds = torch.sigmoid(outputs).cpu().numpy()
        all_preds.extend(preds)
        all_labels.extend(labels.cpu().numpy())

# --- METRIC CALCULATION SKELETON (DO NOT CHANGE THE LOGIC BELOW) ---
all_preds = np.array(all_preds)
y_true_one_hot = np.eye(NUM_SPECIES)[np.array(all_labels)]

# 1. Bulletproof mask: Check that the column has at least one positive AND at least one negative.
# This handles floats, booleans, label smoothing, and prevents sklearn division-by-zero crashes.
col_sums = np.sum(y_true_one_hot, axis=0)
valid_classes = (col_sums > 0) & (col_sums < len(y_true_one_hot))

# 2. Safe AUC calculation
if np.any(valid_classes):
    filtered_true = y_true_one_hot[:, valid_classes]
    filtered_preds = all_preds[:, valid_classes]

    try:
        final_auc = float(roc_auc_score(filtered_true, filtered_preds, average='macro', multi_class='ovr'))
    except ValueError:
        final_auc = 0.5000  # Failsafe if sklearn still complains
else:
    final_auc = 0.5000

print(f"Final Validation AUC: {final_auc:.4f}")

# Save Metrics (with type ignores to silence Pylance)
metrics = {
    "final_train_loss": all_train_losses[-1] if 'all_train_losses' in locals() and all_train_losses else 0.0, # type: ignore
    "final_auc": final_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": max_epochs,
    "batch_size": 128, 
    "training_samples": len(train_loader.dataset),  # type: ignore
    "eval_samples": len(val_loader.dataset)  # type: ignore
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print("METRICS: ", json.dumps(metrics))

# Save Model
torch.save(model.state_dict(), 'model.pt')